INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('asv','GEN',1,1,'In the beginning God created the heavens and the earth.',NULL),
('asv','GEN',1,2,'And the earth was waste and void; and darkness was upon the face of the deep: and the Spirit of God moved upon the face of the waters.',NULL),
('asv','GEN',1,3,'And God said, Let there be light: and there was light.',NULL),
('asv','GEN',1,4,'And God saw the light, that it was good: and God divided the light from the darkness.',NULL),
('asv','GEN',1,5,'And God called the light Day, and the darkness he called Night. And there was evening and there was morning, one day.',NULL),
('asv','GEN',1,6,'And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters.',NULL),
('asv','GEN',1,7,'And God made the firmament, and divided the waters which were under the firmament from the waters which were above the firmament: and it was so.',NULL),
('asv','GEN',1,8,'And God called the firmament Heaven. And there was evening and there was morning, a second day.',NULL),
('asv','GEN',1,9,'And God said, Let the waters under the heavens be gathered together unto one place, and let the dry land appear: and it was so.',NULL),
('asv','GEN',1,10,'And God called the dry land Earth; and the gathering together of the waters called he Seas: and God saw that it was good.',NULL),
('asv','GEN',1,11,'And God said, Let the earth put forth grass, herbs yielding seed, [and] fruit-trees bearing fruit after their kind, wherein is the seed thereof, upon the earth: and it was so.',NULL),
('asv','GEN',1,12,'And the earth brought forth grass, herbs yielding seed after their kind, and trees bearing fruit, wherein is the seed thereof, after their kind: and God saw that it was good.',NULL),
('asv','GEN',1,13,'And there was evening and there was morning, a third day.',NULL),
('asv','GEN',1,14,'And God said, Let there be lights in the firmament of heaven to divide the day from the night; and let them be for signs, and for seasons, and for days and years:',NULL),
('asv','GEN',1,15,'and let them be for lights in the firmament of heaven to give light upon the earth: and it was so.',NULL),
('asv','GEN',1,16,'And God made the two great lights; the greater light to rule the day, and the lesser light to rule the night: [he made] the stars also.',NULL),
('asv','GEN',1,17,'And God set them in the firmament of heaven to give light upon the earth,',NULL),
('asv','GEN',1,18,'and to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good.',NULL),
('asv','GEN',1,19,'And there was evening and there was morning, a fourth day.',NULL),
('asv','GEN',1,20,'And God said, Let the waters swarm with swarms of living creatures, and let birds fly above the earth in the open firmament of heaven.',NULL),
('asv','GEN',1,21,'And God created the great sea-monsters, and every living creature that moveth, wherewith the waters swarmed, after their kind, and every winged bird after its kind: and God saw that it was good.',NULL),
('asv','GEN',1,22,'And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let birds multiply on the earth.',NULL),
('asv','GEN',1,23,'And there was evening and there was morning, a fifth day.',NULL),
('asv','GEN',1,24,'And God said, Let the earth bring forth living creatures after their kind, cattle, and creeping things, and beasts of the earth after their kind: and it was so.',NULL),
('asv','GEN',1,25,'And God made the beasts of the earth after their kind, and the cattle after their kind, and everything that creepeth upon the ground after its kind: and God saw that it was good.',NULL),
('asv','GEN',1,26,'And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the birds of the heavens, and over the cattle, and over all the earth, and over every creeping thing that creepeth upon the earth.',NULL),
('asv','GEN',1,27,'And God created man in his own image, in the image of God created he him; male and female created he them.',NULL),
('asv','GEN',1,28,'And God blessed them: and God said unto them, Be fruitful, and multiply, and replenish the earth, and subdue it; and have dominion over the fish of the sea, and over the birds of the heavens, and over every living thing that moveth upon the earth.',NULL),
('asv','GEN',1,29,'And God said, Behold, I have given you every herb yielding seed, which is upon the face of all the earth, and every tree, in which is the fruit of a tree yielding seed; to you it shall be for food:',NULL),
('asv','GEN',1,30,'and to every beast of the earth, and to every bird of the heavens, and to everything that creepeth upon the earth, wherein there is life, [I have given] every green herb for food: and it was so.',NULL),
('asv','GEN',1,31,'And God saw everything that he had made, and, behold, it was very good. And there was evening and there was morning, the sixth day.',NULL),
('asv','PSA',23,1,'Jehovah is my shepherd; I shall not want.',NULL),
('asv','PSA',23,2,'He maketh me to lie down in green pastures; He leadeth me beside still waters.',NULL),
('asv','PSA',23,3,'He restoreth my soul: He guideth me in the paths of righteousness for his name’s sake.',NULL),
('asv','PSA',23,4,'Yea, though I walk through the valley of the shadow of death, I will fear no evil; for thou art with me; Thy rod and thy staff, they comfort me.',NULL),
('asv','PSA',23,5,'Thou preparest a table before me in the presence of mine enemies: Thou hast anointed my head with oil; My cup runneth over.',NULL),
('asv','PSA',23,6,'Surely goodness and lovingkindness shall follow me all the days of my life; And I shall dwell in the house of Jehovah for ever.',NULL),
('asv','PSA',117,1,'O praise Jehovah, all ye nations; Laud him, all ye peoples.',NULL),
('asv','PSA',117,2,'For his lovingkindness is great toward us; And the truth of Jehovah [endureth] for ever. Praise ye Jehovah.',NULL),
('asv','MAT',11,1,'And it came to pass when Jesus had finished commanding his twelve disciples, he departed thence to teach and preach in their cities.',NULL),
('asv','MAT',11,2,'Now when John heard in the prison the works of the Christ, he sent by his disciples',NULL),
('asv','MAT',11,3,'and said unto him, Art thou he that cometh, or look we for another?',NULL),
('asv','MAT',11,4,'And Jesus answered and said unto them, Go and tell John the things which ye hear and see:',NULL),
('asv','MAT',11,5,'the blind receive their sight, and the lame walk, the lepers are cleansed, and the deaf hear, and the dead are raised up, and the poor have good tidings preached to them.',NULL),
('asv','MAT',11,6,'And blessed is he, whosoever shall find no occasion of stumbling in me.',NULL),
('asv','MAT',11,7,'And as these went their way, Jesus began to say unto the multitudes concerning John, What went ye out into the wilderness to behold? a reed shaken with the wind?',NULL),
('asv','MAT',11,8,'But what went ye out to see? a man clothed in soft [raiment]? Behold, they that wear soft [raiment] are in kings’ houses.',NULL),
('asv','MAT',11,9,'But wherefore went ye out? to see a prophet? Yea, I say unto you, and much more than a prophet.',NULL),
('asv','MAT',11,10,'This is he, of whom it is written, Behold, I send my messenger before thy face, Who shall prepare thy way before thee.',NULL),
('asv','MAT',11,11,'Verily I say unto you, Among them that are born of women there hath not arisen a greater than John the Baptist: yet he that is but little in the kingdom of heaven is greater than he.',NULL),
('asv','MAT',11,12,'And from the days of John the Baptist until now the kingdom of heaven suffereth violence, and men of violence take it by force.',NULL),
('asv','MAT',11,13,'For all the prophets and the law prophesied until John.',NULL),
('asv','MAT',11,14,'And if ye are willing to receive [it], this is Elijah, that is to come.',NULL),
('asv','MAT',11,15,'He that hath ears to hear, let him hear.',NULL),
('asv','MAT',11,16,'But whereunto shall I liken this generation? It is like unto children sitting in the marketplaces, who call unto their fellows',NULL),
('asv','MAT',11,17,'and say, We piped unto you, and ye did not dance; we wailed, and ye did not mourn.',NULL),
('asv','MAT',11,18,'For John came neither eating nor drinking, and they say, He hath a demon.',NULL),
('asv','MAT',11,19,'The Son of man came eating and drinking, and they say, Behold, a gluttonous man and a winebibber, a friend of publicans and sinners! And wisdom is justified by her works.',NULL),
('asv','MAT',11,20,'Then began he to upbraid the cities wherein most of his mighty works were done, because they repented not.',NULL),
('asv','MAT',11,21,'Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works had been done in Tyre and Sidon which were done in you, they would have repented long ago in sackcloth and ashes.',NULL),
('asv','MAT',11,22,'But I say unto you, it shall be more tolerable for Tyre and Sidon in the day of judgment, than for you.',NULL),
('asv','MAT',11,23,'And thou, Capernaum, shalt thou be exalted unto heaven? thou shalt go down unto Hades: for if the mighty works had been done in Sodom which were done in thee, it would have remained until this day.',NULL),
('asv','MAT',11,24,'But I say unto you that it shall be more tolerable for the land of Sodom in the day of judgment, than for thee.',NULL),
('asv','MAT',11,25,'At that season Jesus answered and said, I thank thee, O Father, Lord of heaven and earth, that thou didst hide these things from the wise and understanding, and didst reveal them unto babes:',NULL),
('asv','MAT',11,26,'yea, Father, for so it was well-pleasing in thy sight.',NULL),
('asv','MAT',11,27,'All things have been delivered unto me of my Father: and no one knoweth the Son, save the Father; neither doth any know the Father, save the Son, and he to whomsoever the Son willeth to reveal [him].',NULL),
('asv','MAT',11,28,'Come unto me, all ye that labor and are heavy laden, and I will give you rest.',NULL),
('asv','MAT',11,29,'Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls.',NULL),
('asv','MAT',11,30,'For my yoke is easy, and my burden is light.',NULL),
('asv','MAT',17,1,'And after six days Jesus taketh with him Peter, and James, and John his brother, and bringeth them up into a high mountain apart:',NULL),
('asv','MAT',17,2,'and he was transfigured before them; and his face did shine as the sun, and his garments became white as the light.',NULL),
('asv','MAT',17,3,'And behold, there appeared unto them Moses and Elijah talking with him.',NULL),
('asv','MAT',17,4,'And Peter answered, and said unto Jesus, Lord, it is good for us to be here: if thou wilt, I will make here three tabernacles; one for thee, and one for Moses, and one for Elijah.',NULL),
('asv','MAT',17,5,'While he was yet speaking, behold, a bright cloud overshadowed them: and behold, a voice out of the cloud, saying, This is my beloved Son, in whom I am well pleased; hear ye him.',NULL),
('asv','MAT',17,6,'And when the disciples heard it, they fell on their face, and were sore afraid.',NULL),
('asv','MAT',17,7,'And Jesus came and touched them and said, Arise, and be not afraid.',NULL),
('asv','MAT',17,8,'And lifting up their eyes, they saw no one, save Jesus only.',NULL),
('asv','MAT',17,9,'And as they were coming down from the mountain, Jesus commanded them, saying, Tell the vision to no man, until the Son of man be risen from the dead.',NULL),
('asv','MAT',17,10,'And his disciples asked him, saying, Why then say the scribes that Elijah must first come?',NULL),
('asv','MAT',17,11,'And he answered and said, Elijah indeed cometh, and shall restore all things:',NULL),
('asv','MAT',17,12,'but I say unto you, that Elijah is come already, and they knew him not, but did unto him whatsoever they would. Even so shall the Son of man also suffer of them.',NULL),
('asv','MAT',17,13,'Then understood the disciples that he spake unto them of John the Baptist.',NULL),
('asv','MAT',17,14,'And when they were come to the multitude, there came to him a man, kneeling to him, and saying,',NULL),
('asv','MAT',17,15,'Lord, have mercy on my son: for he is epileptic, and suffereth grievously; for oft-times he falleth into the fire, and oft-times into the water.',NULL),
('asv','MAT',17,16,'And I brought him to thy disciples, and they could not cure him.',NULL),
('asv','MAT',17,17,'And Jesus answered and said, O faithless and perverse generation, how long shall I be with you? how long shall I bear with you? bring him hither to me.',NULL),
('asv','MAT',17,18,'And Jesus rebuked him; and the demon went out of him: and the boy was cured from that hour.',NULL),
('asv','MAT',17,19,'Then came the disciples to Jesus apart, and said, Why could not we cast it out?',NULL),
('asv','MAT',17,20,'And he saith unto them, Because of your little faith: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.',NULL),
('asv','MAT',17,22,'And while they abode in Galilee, Jesus said unto them, The Son of man shall be delivered up into the hands of men;',NULL),
('asv','MAT',17,23,'and they shall kill him, and the third day he shall be raised up. And they were exceeding sorry.',NULL),
('asv','MAT',17,24,'And when they were come to Capernaum, they that received the half-shekel came to Peter, and said, Doth not your teacher pay the half-shekel?',NULL),
('asv','MAT',17,25,'He saith, Yea. And when he came into the house, Jesus spake first to him, saying, What thinkest thou, Simon? the kings of the earth, from whom do they receive toll or tribute? from their sons, or from strangers?',NULL),
('asv','MAT',17,26,'And when he said, From strangers, Jesus said unto him, Therefore the sons are free.',NULL),
('asv','MAT',17,27,'But, lest we cause them to stumble, go thou to the sea, and cast a hook, and take up the fish that first cometh up; and when thou hast opened his mouth, thou shalt find a shekel: that take, and give unto them for me and thee.',NULL),
('asv','JHN',3,1,'Now there was a man of the Pharisees, named Nicodemus, a ruler of the Jews:',NULL),
('asv','JHN',3,2,'the same came unto him by night, and said to him, Rabbi, we know that thou art a teacher come from God; for no one can do these signs that thou doest, except God be with him.',NULL),
('asv','JHN',3,3,'Jesus answered and said unto him, Verily, verily, I say unto thee, Except one be born anew, he cannot see the kingdom of God.',NULL),
('asv','JHN',3,4,'Nicodemus saith unto him, How can a man be born when he is old? can he enter a second time into his mother’s womb, and be born?',NULL),
('asv','JHN',3,5,'Jesus answered, Verily, verily, I say unto thee, Except one be born of water and the Spirit, he cannot enter into the kingdom of God.',NULL),
('asv','JHN',3,6,'That which is born of the flesh is flesh; and that which is born of the Spirit is spirit.',NULL),
('asv','JHN',3,7,'Marvel not that I said unto thee, Ye must be born anew.',NULL),
('asv','JHN',3,8,'The wind bloweth where it will, and thou hearest the voice thereof, but knowest not whence it cometh, and whither it goeth: so is every one that is born of the Spirit.',NULL),
('asv','JHN',3,9,'Nicodemus answered and said unto him, How can these things be?',NULL),
('asv','JHN',3,10,'Jesus answered and said unto him, Art thou the teacher of Israel, and understandest not these things?',NULL),
('asv','JHN',3,11,'Verily, verily, I say unto thee, We speak that which we know, and bear witness of that which we have seen; and ye receive not our witness.',NULL),
('asv','JHN',3,12,'If I told you earthly things and ye believe not, how shall ye believe if I tell you heavenly things?',NULL),
('asv','JHN',3,13,'And no one hath ascended into heaven, but he that descended out of heaven, [even] the Son of man, who is in heaven.',NULL),
('asv','JHN',3,14,'And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up;',NULL),
('asv','JHN',3,15,'that whosoever believeth may in him have eternal life.',NULL),
('asv','JHN',3,16,'For God so loved the world, that he gave his only begotten Son, that whosoever believeth on him should not perish, but have eternal life.',NULL),
('asv','JHN',3,17,'For God sent not the Son into the world to judge the world; but that the world should be saved through him.',NULL),
('asv','JHN',3,18,'He that believeth on him is not judged: he that believeth not hath been judged already, because he hath not believed on the name of the only begotten Son of God.',NULL),
('asv','JHN',3,19,'And this is the judgment, that the light is come into the world, and men loved the darkness rather than the light; for their works were evil.',NULL),
('asv','JHN',3,20,'For every one that doeth evil hateth the light, and cometh not to the light, lest his works should be reproved.',NULL),
('asv','JHN',3,21,'But he that doeth the truth cometh to the light, that his works may be made manifest, that they have been wrought in God.',NULL),
('asv','JHN',3,22,'After these things came Jesus and his disciples into the land of Judæa; and there he tarried with them, and baptized.',NULL),
('asv','JHN',3,23,'And John also was baptizing in Ænon near to Salim, because there was much water there: and they came, and were baptized.',NULL),
('asv','JHN',3,24,'For John was not yet cast into prison.',NULL),
('asv','JHN',3,25,'There arose therefore a questioning on the part of John’s disciples with a Jew about purifying.',NULL),
('asv','JHN',3,26,'And they came unto John, and said to him, Rabbi, he that was with thee beyond the Jordan, to whom thou hast borne witness, behold, the same baptizeth, and all men come to him.',NULL),
('asv','JHN',3,27,'John answered and said, A man can receive nothing, except it have been given him from heaven.',NULL),
('asv','JHN',3,28,'Ye yourselves bear me witness, that I said, I am not the Christ, but, that I am sent before him.',NULL),
('asv','JHN',3,29,'He that hath the bride is the bridegroom: but the friend of the bridegroom, that standeth and heareth him, rejoiceth greatly because of the bridegroom’s voice: this my joy therefore is made full.',NULL),
('asv','JHN',3,30,'He must increase, but I must decrease.',NULL),
('asv','JHN',3,31,'He that cometh from above is above all: he that is of the earth is of the earth, and of the earth he speaketh: he that cometh from heaven is above all.',NULL),
('asv','JHN',3,32,'What he hath seen and heard, of that he beareth witness; and no man receiveth his witness.',NULL),
('asv','JHN',3,33,'He that hath received his witness hath set his seal to [this], that God is true.',NULL),
('asv','JHN',3,34,'For he whom God hath sent speaketh the words of God: for he giveth not the Spirit by measure.',NULL),
('asv','JHN',3,35,'The Father loveth the Son, and hath given all things into his hand.',NULL),
('asv','JHN',3,36,'He that believeth on the Son hath eternal life; but he that obeyeth not the Son shall not see life, but the wrath of God abideth on him.',NULL),
('asv','3JN',1,1,'The elder unto Gaius the beloved, whom I love in truth.',NULL),
('asv','3JN',1,2,'Beloved, I pray that in all things thou mayest prosper and be in health, even as thy soul prospereth.',NULL),
('asv','3JN',1,3,'For I rejoiced greatly, when brethren came and bare witness unto thy truth, even as thou walkest in truth.',NULL),
('asv','3JN',1,4,'Greater joy have I none than this, to hear of my children walking in the truth.',NULL),
('asv','3JN',1,5,'Beloved, thou doest a faithful work in whatsoever thou doest toward them that are brethren and strangers withal;',NULL),
('asv','3JN',1,6,'who bare witness to thy love before the church: whom thou wilt do well to set forward on their journey worthily of God:',NULL),
('asv','3JN',1,7,'because that for the sake of the Name they went forth, taking nothing of the Gentiles.',NULL),
('asv','3JN',1,8,'We therefore ought to welcome such, that we may be fellow-workers for the truth.',NULL),
('asv','3JN',1,9,'I wrote somewhat unto the church: but Diotrephes, who loveth to have the preeminence among them, receiveth us not.',NULL),
('asv','3JN',1,10,'Therefore, if I come, I will bring to remembrance his works which he doeth, prating against us with wicked words: and not content therewith, neither doth he himself receive the brethren, and them that would he forbiddeth and casteth [them] out of the church.',NULL),
('asv','3JN',1,11,'Beloved, imitate not that which is evil, but that which is good. He that doeth good is of God: he that doeth evil hath not seen God.',NULL),
('asv','3JN',1,12,'Demetrius hath the witness of all [men], and of the truth itself: yea, we also bear witness; and thou knowest that our witness is true.',NULL),
('asv','3JN',1,13,'I had many things to write unto thee, but I am unwilling to write [them] to thee with ink and pen:',NULL),
('asv','3JN',1,14,'but I hope shortly to see thee, and we shall speak face to face. Peace [be] unto thee. The friends salute thee. Salute the friends by name.',NULL),
('asv','REV',12,1,'And a great sign was seen in heaven: a woman arrayed with the sun, and the moon under her feet, and upon her head a crown of twelve stars;',NULL),
('asv','REV',12,2,'and she was with child; and she crieth out, travailing in birth, and in pain to be delivered.',NULL),
('asv','REV',12,3,'And there was seen another sign in heaven: and behold, a great red dragon, having seven heads and ten horns, and upon his heads seven diadems.',NULL),
('asv','REV',12,4,'And his tail draweth the third part of the stars of heaven, and did cast them to the earth: and the dragon standeth before the woman that is about to be delivered, that when she is delivered he may devour her child.',NULL),
('asv','REV',12,5,'And she was delivered of a son, a man child, who is to rule all the nations with a rod of iron: and her child was caught up unto God, and unto his throne.',NULL),
('asv','REV',12,6,'And the woman fled into the wilderness, where she hath a place prepared of God, that there they may nourish her a thousand two hundred and threescore days.',NULL),
('asv','REV',12,7,'And there was war in heaven: Michael and his angels [going forth] to war with the dragon; and the dragon warred and his angels;',NULL),
('asv','REV',12,8,'and they prevailed not, neither was their place found any more in heaven.',NULL),
('asv','REV',12,9,'And the great dragon was cast down, the old serpent, he that is called the Devil and Satan, the deceiver of the whole world; he was cast down to the earth, and his angels were cast down with him.',NULL),
('asv','REV',12,10,'And I heard a great voice in heaven, saying, Now is come the salvation, and the power, and the kingdom of our God, and the authority of his Christ: for the accuser of our brethren is cast down, who accuseth them before our God day and night.',NULL),
('asv','REV',12,11,'And they overcame him because of the blood of the Lamb, and because of the word of their testimony; and they loved not their life even unto death.',NULL),
('asv','REV',12,12,'Therefore rejoice, O heavens, and ye that dwell in them. Woe for the earth and for the sea: because the devil is gone down unto you, having great wrath, knowing that he hath but a short time.',NULL),
('asv','REV',12,13,'And when the dragon saw that he was cast down to the earth, he persecuted the woman that brought forth the man [child].',NULL),
('asv','REV',12,14,'And there were given to the woman the two wings of the great eagle, that she might fly into the wilderness unto her place, where she is nourished for a time, and times, and half a time, from the face of the serpent.',NULL),
('asv','REV',12,15,'And the serpent cast out of his mouth after the woman water as a river, that he might cause her to be carried away by the stream.',NULL),
('asv','REV',12,16,'And the earth helped the woman, and the earth opened her mouth and swallowed up the river which the dragon cast out of his mouth.',NULL),
('asv','REV',12,17,'And the dragon waxed wroth with the woman, and went away to make war with the rest of her seed, that keep the commandments of God, and hold the testimony of Jesus:',NULL);
INSERT INTO chapter_titles (translation_id, book_id, chapter, text) VALUES
('asv','PSA',23,'A Psalm of David.');
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
